package com.nearnow.vendor;
import java.time.Instant;
public class RestockRequestResponseDTO { private Long id; private Long productId; private String productName; private int quantity; private String note; private RestockRequestStatus status; private Instant createdAt; public RestockRequestResponseDTO(Long id,Long productId,String productName,int quantity,String note,RestockRequestStatus status,Instant createdAt){this.id=id;this.productId=productId;this.productName=productName;this.quantity=quantity;this.note=note;this.status=status;this.createdAt=createdAt;} public Long getId(){return id;} public Long getProductId(){return productId;} public String getProductName(){return productName;} public int getQuantity(){return quantity;} public String getNote(){return note;} public RestockRequestStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} }
